(()=>{const root=document.documentElement;let lang='th';try{lang=localStorage.getItem('bcsm-lang')||'th'}catch{}const q=new URLSearchParams(location.search).get('lang');if(q==='th'||q==='en')lang=q;root.lang=lang==='en'?'en':'th';document.addEventListener('DOMContentLoaded',()=>{const language=document.getElementById('langBtn'),menu=document.getElementById('menuBtn'),nav=document.getElementById('mainNav');language?.addEventListener('click',()=>{root.lang=root.lang==='th'?'en':'th';try{localStorage.setItem('bcsm-lang',root.lang)}catch{}updateCaption()});const closeMenu=()=>{nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false')};menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav?.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))closeMenu()});window.matchMedia('(min-width:1001px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
const filters=[...document.querySelectorAll('[data-filter]')],items=[...document.querySelectorAll('.gallery-item')],dialog=document.getElementById('galleryDialog'),modalImg=document.getElementById('modalImg'),caption=document.getElementById('modalCaption');let current=0,lastFocus=null;
const sceneButtons=[...document.querySelectorAll('[data-render]')],sceneImage=document.getElementById('designRender');sceneButtons.forEach(b=>b.addEventListener('click',()=>{sceneButtons.forEach(other=>other.setAttribute('aria-pressed',String(other===b)));sceneImage.src=b.dataset.render;sceneImage.alt=root.lang==='th'?b.dataset.altTh:b.dataset.altEn}));
filters.forEach(filter=>filter.addEventListener('click',()=>{filters.forEach(f=>f.setAttribute('aria-pressed',String(f===filter)));items.forEach(item=>item.hidden=filter.dataset.filter!=='all'&&item.dataset.category!==filter.dataset.filter);const count=items.filter(i=>!i.hidden).length;const status=document.getElementById('galleryStatus');if(status)status.textContent=root.lang==='th'?`แสดง ${count} ภาพ`:`Showing ${count} photographs`;}));
function updateCaption(){if(!items.length||!caption)return;const item=items[current];const text=root.lang==='th'?item.dataset.th:item.dataset.en;caption.textContent=text;modalImg.alt=text}
function show(index){if(!dialog)return;current=(index+items.length)%items.length;modalImg.src=items[current].dataset.src;updateCaption()}
items.forEach((item,index)=>item.addEventListener('click',()=>{lastFocus=item;show(index);dialog.showModal();document.body.style.overflow='hidden'}));document.getElementById('modalClose')?.addEventListener('click',()=>dialog.close());document.getElementById('modalPrev')?.addEventListener('click',()=>show(current-1));document.getElementById('modalNext')?.addEventListener('click',()=>show(current+1));dialog?.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus()});dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog?.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();show(current-1)}if(e.key==='ArrowRight'){e.preventDefault();show(current+1)}});
});})();
